import{_ as e,o as t,c as o,a4 as l}from"./chunks/framework.Cp_kp8rY.js";const _=JSON.parse('{"title":"并发编程_基础概念_补充内容","description":"","frontmatter":{"title":"并发编程_基础概念_补充内容","date":"2024-03-09 10:28:43","updated":"2024-03-09 10:28:43"},"headers":[],"relativePath":"notes/0/1/1.5/1.5.1/1.5.1.6/1.5.1.6.2/Java并发编程_基础概念_补充内容.md","filePath":"notes/0/1/1.5/1.5.1/1.5.1.6/1.5.1.6.2/Java并发编程_基础概念_补充内容.md"}'),n={name:"notes/0/1/1.5/1.5.1/1.5.1.6/1.5.1.6.2/Java并发编程_基础概念_补充内容.md"};function s(c,a,r,p,i,d){return t(),o("div",null,[...a[0]||(a[0]=[l(`<h4 id="aqs" tabindex="-1">AQS <a class="header-anchor" href="#aqs" aria-label="Permalink to &quot;AQS&quot;">​</a></h4><p><code>AbstractQueuedSynchronizer</code> (AQS) 是 Java 并发包中的一个核心类，是许多同步组件的基础，比如 <code>ReentrantLock</code>, <code>Semaphore</code>, <code>CountDownLatch</code>, <code>ReentrantReadWriteLock</code> 等。</p><p>它提供了一种实现依赖于先进先出 (FIFO) 等待队列的阻塞锁和相关的同步器（semaphores, events, etc.）的框架。</p><p>AQS 是一个抽象类，定义了同步状态的获取和释放方法。</p><h4 id="谈一下java的共享内存模型jmm" tabindex="-1">谈⼀下Java的共享内存模型JMM <a class="header-anchor" href="#谈一下java的共享内存模型jmm" aria-label="Permalink to &quot;谈⼀下Java的共享内存模型JMM&quot;">​</a></h4><p>JMM 是什么：</p><p>JMM 是 Java 并发编程相关的一组规范，它抽象了线程和主内存之间的关系，提供了一致性和可见性保证。</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240309105232.png" alt="image.png"></p><p>核心概念</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240309105324.png" alt="image.png"></p><p>可以了解一下 MESI 协议</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240309105433.png" alt="image.png"></p><h4 id="谈一下volatile" tabindex="-1">谈⼀下volatile <a class="header-anchor" href="#谈一下volatile" aria-label="Permalink to &quot;谈⼀下volatile&quot;">​</a></h4><h4 id="threadlocal" tabindex="-1">ThreadLocal <a class="header-anchor" href="#threadlocal" aria-label="Permalink to &quot;ThreadLocal&quot;">​</a></h4><p>ThreadLocal 一般是用作独立变量副本（线程的变量副本），避免线程共享变量可能导致的并发问题。</p><p>建议先看一下这篇文章： <a href="https://cloud.tencent.com/developer/article/1636025" target="_blank" rel="noreferrer">https://cloud.tencent.com/developer/article/1636025</a></p><p>ThreadLocal包含了四个方法:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>void set(Object value)设置当前线程的线程局部变量的值。</span></span>
<span class="line"><span>public Object get()该方法返回当前线程所对应的线程局部变量。</span></span>
<span class="line"><span>public void remove()将当前线程局部变量的值删除，其目的是为了减少内存使用，加快内存回收。</span></span>
<span class="line"><span>protected Object initialValue()返回该线程局部变量的初始值，该方法是一个protected的方法，目的是为了让子类覆盖而设计的。</span></span></code></pre></div><p>使用到 ThreadLocal 的三个常用场景：</p><ul><li><ol><li>代替参数的显示传递</li></ol></li><li><ol start="2"><li>全局存储用户信息</li></ol></li><li><ol start="3"><li>解决线程安全问题（比如数据库连接的Connection)</li></ol></li></ul><p>慎用的场景：线程池中线程调用使用ThreadLocal、异步程序；同时注意的是使用完ThreadLocal ，最好手动调用 remove() 方法。</p><hr><p>关于 ThreadLocal 的数据结构，方法源码，扩容机制等可以看一下这篇文章： <a href="https://javaguide.cn/java/concurrent/threadlocal.html" target="_blank" rel="noreferrer">https://javaguide.cn/java/concurrent/threadlocal.html</a></p>`,23)])])}const u=e(n,[["render",s]]);export{_ as __pageData,u as default};
